theorem finite_forall {κ : Type*} (S : Finset κ) (f : κ → Set (ι → ℝ))
    (hf : ∀ k ∈ S, IsSemialgebraic ι (f k)) :
    IsSemialgebraic ι {x | ∀ k ∈ S, x ∈ f k}

theorem affineTorus_coordinate_bounds {d : ℕ} {x : TorusAmbient d}
    (hx : x ∈ affineTorus d) (i : Fin d) :
    ‖x (.inl i)‖ ≤ ‖x‖ ∧ ‖(x (.inl i))⁻¹‖ ≤ ‖x‖

theorem smallGradientSphere_isClosed {d : ℕ}
    (g : Fin d → AmbientPolynomial d) (R ε : ℝ) :
    IsClosed (smallGradientSphere g R ε)

theorem smallGradientSphere_isCompact {d : ℕ}
    (g : Fin d → AmbientPolynomial d) (R ε : ℝ) :
    IsCompact (smallGradientSphere g R ε)

theorem isComplexSemialgebraic_affineTorus (d : ℕ) :
    IsComplexSemialgebraic {x : (Fin d ⊕ Fin d) → ℂ |
      WithLp.toLp 2 x ∈ affineTorus d}

theorem isComplexSemialgebraic_ambientDifferentialNorm_le {d : ℕ}
    (g : Fin d → AmbientPolynomial d) {ε : ℝ} (hε : 0 ≤ ε) :
    IsComplexSemialgebraic {x : (Fin d ⊕ Fin d) → ℂ |
      ambientDifferentialNorm g (WithLp.toLp 2 x) ≤ ε}

theorem isComplexSemialgebraic_euclidean_sphere {ι : Type*} [Fintype ι]
    {R : ℝ} (hR : 0 ≤ R) :
    IsComplexSemialgebraic {x : ι → ℂ | ‖WithLp.toLp 2 x‖ = R}

theorem restrictedDifferential_of_hasFDerivAt {d : ℕ} {z g : Fin d → ℂ}
    (hz : ∀ i, z i ≠ 0) {F : TorusAmbient d → ℂ} {D : TorusAmbient d →L[ℂ] ℂ}
    (hF : HasFDerivAt F D (torusEmbed z))
    (hf : HasFDerivAt (F ∘ torusEmbed) (coordinateDifferential g) z) :
    D.comp (torusTangentSpace z).subtypeL = restrictedDifferential z g

theorem restricted_fderiv_norm_sq {d : ℕ} {z g : Fin d → ℂ}
    (hz : ∀ i, z i ≠ 0) {F : TorusAmbient d → ℂ} {D : TorusAmbient d →L[ℂ] ℂ}
    (hF : HasFDerivAt F D (torusEmbed z))
    (hf : HasFDerivAt (F ∘ torusEmbed) (coordinateDifferential g) z) :
    ‖D.comp (torusTangentSpace z).subtypeL‖ ^ 2 =
      ∑ i, Complex.normSq (g i) / (1 + ‖z i‖⁻¹ ^ 4)

theorem smooth_lipschitz_on_compact {V : E → E} {K : Set E}
    (hK : IsCompact K) (hV : ∀ x ∈ K, ContDiffAt ℝ 1 V x) :
    ∃ L, LipschitzOnWith L V K

theorem curveTorusWeight_apply {d : ℕ} {z : Fin d → C(X, ℂ)}
    (hz : ∀ i t, z i t ≠ 0) (i : Fin d) (t : X) :
    curveTorusWeight z i t = torusWeight (fun j => z j t) i

theorem curveTorusWeight_contDiffAt {d : ℕ} {z : Fin d → C(X, ℂ)}
    (hz : ∀ i t, z i t ≠ 0) (i : Fin d) :
    ContDiffAt ℝ ⊤ (fun u => curveTorusWeight u i) z

theorem curveVectorField_contDiffAt {d : ℕ} (p : AmbientPolynomial d) {a : ℂ}
    {z : Fin d → C(X, ℂ)}
    (hz : ∀ t, (fun i => z i t) ∈ polynomialRegularDomain p) :
    ContDiffAt ℝ ⊤ (fun az : ℂ × (Fin d → C(X, ℂ)) => curveVectorField p az.1 az.2)
      (a, z)

theorem laurentCurveVectorField_contDiffAt {d : ℕ} (f : MultiLaurent d) {a : ℂ}
    {z : Fin d → C(X, ℂ)}
    (hz : ∀ t, (fun i => z i t) ∈ laurentRegularDomain f) :
    ContDiffAt ℝ ⊤ (fun az : ℂ × (Fin d → C(X, ℂ)) =>
      curveVectorField (laurentRepresentative f) az.1 az.2) (a, z)

theorem isComplexSemialgebraic_criticalTorusLocus {d : ℕ} (p : AmbientPolynomial d) :
    IsComplexSemialgebraic {x : (Fin d ⊕ Fin d) → ℂ |
      WithLp.toLp 2 x ∈ criticalTorusLocus p}

theorem finite_uniform_separation {Y : Type*} [MetricSpace Y] {n : ℕ}
    (c : Fin (n + 1) → Y) (hc : Function.Injective c) :
    ∃ η > (0 : ℝ), ∀ i j, i ≠ j → η ≤ dist (c i) (c j)

theorem isSemialgebraic_polynomial_dist_lt {ι κ : Type*}
    (p : MvPolynomial ι ℂ) (Z : (ι ⊕ ι) → MvPolynomial κ ℝ)
    (c : ℂ) (e : MvPolynomial κ ℝ) :
    IsSemialgebraic κ {x | 0 ≤ MvPolynomial.eval x e ∧
      dist (MvPolynomial.eval (complexCoordinates (fun i => MvPolynomial.eval x (Z i))) p) c <
        MvPolynomial.eval x e}

theorem IsSemialgebraic.eventuallyConstant_polynomial_curve {ι : Type*}
    {S : Set (ι → ℝ)} (hS : IsSemialgebraic ι S) (g : ι → Polynomial ℝ) :
    EventuallyConstant (fun t => (fun i => (g i).eval t) ∈ S)

theorem isComplexSemialgebraic_smallGradientSphere {d : ℕ}
    (g : Fin d → AmbientPolynomial d) {R ε : ℝ} (hR : 1 < R) (hε : 0 < ε) :
    IsComplexSemialgebraic {x : (Fin d ⊕ Fin d) → ℂ |
      WithLp.toLp 2 x ∈ smallGradientSphere g R ε}

theorem section_add {U : Opens X} {f g : ∀ x : U, H x.val}
    (hf : A.toAtlas.sectionPredicate.pred f) (hg : A.toAtlas.sectionPredicate.pred g) :
    A.toAtlas.sectionPredicate.pred (fun x => f x + g x)

theorem section_smul {U : Opens X} (r : ℤ) {f : ∀ x : U, H x.val}
    (hf : A.toAtlas.sectionPredicate.pred f) :
    A.toAtlas.sectionPredicate.pred (fun x => r • f x)

theorem IsSemialgebraic.finite_components_polynomial_curve {ι : Type*}
    {S : Set (ι → ℝ)} (hS : IsSemialgebraic ι S) (g : ι → Polynomial ℝ) :
    Finite (ConnectedComponents {t : ℝ | (fun i => (g i).eval t) ∈ S})

theorem IsSemialgebraic.finite_convex_cover_polynomial_curve {ι : Type*}
    {S : Set (ι → ℝ)} (hS : IsSemialgebraic ι S) (g : ι → Polynomial ℝ) :
    ∃ C : Set (Set ℝ), C.Finite ∧ (∀ A ∈ C, Convex ℝ A) ∧
      ⋃₀ C = {t : ℝ | (fun i => (g i).eval t) ∈ S}

theorem IsSemialgebraic.finite_frontier_polynomial_curve {ι : Type*}
    {S : Set (ι → ℝ)} (hS : IsSemialgebraic ι S) (g : ι → Polynomial ℝ) :
    (frontier {t : ℝ | (fun i => (g i).eval t) ∈ S}).Finite

theorem IsSemialgebraic.finite_interval_cover {S : Set (Fin 1 → ℝ)}
    (hS : IsSemialgebraic (Fin 1) S) :
    ∃ C : Set (Set ℝ), C.Finite ∧ (∀ A ∈ C, Set.OrdConnected A) ∧
      ⋃₀ C = {t : ℝ | (fun _ : Fin 1 => t) ∈ S}

theorem exists_finite_convex_cover_of_finite_frontier {S : Set ℝ}
    (hS : (frontier S).Finite) :
    ∃ C : Set (Set ℝ), C.Finite ∧ (∀ A ∈ C, Convex ℝ A) ∧ ⋃₀ C = S

theorem IsSemialgebraic.uniform_convex_cover_polynomial_curves {ι : Type*}
    {S : Set (ι → ℝ)} (hS : IsSemialgebraic ι S) (D : ℕ) :
    ∃ N : ℕ, 1 ≤ N ∧ ∀ g : ι → Polynomial ℝ, (∀ i, (g i).natDegree ≤ D) →
      ∃ C : Set (Set ℝ), C.Finite ∧ C.ncard ≤ N ∧
        (∀ A ∈ C, Convex ℝ A) ∧ ⋃₀ C = {t : ℝ | (fun i => (g i).eval t) ∈ S}

theorem IsSemialgebraic.frontier_polynomial {ι : Type*} {S : Set (ι → ℝ)}
    (hS : IsSemialgebraic ι S) :
    ∃ p : MvPolynomial ι ℝ, p ≠ 0 ∧ frontier S ⊆ {x | MvPolynomial.eval x p = 0}

theorem IsSemialgebraic.polynomial_vanishing_of_empty_interior {ι : Type*}
    {S : Set (ι → ℝ)} (hS : IsSemialgebraic ι S) (hI : interior S = ∅) :
    ∃ p : MvPolynomial ι ℝ, p ≠ 0 ∧ ∀ x ∈ S, MvPolynomial.eval x p = 0

theorem fiberSliceChart_symm_val {k : LaurentFiberModel d}
    (hk : k ∈ (fiberSliceChart e hreg hfst z).target) :
    ((fiberSliceChart e hreg hfst z).symm k).val = e.symm (s, k)

theorem regularLaurentValue_of_not_critical {d : ℕ} (f : MultiLaurent d) {s : ℂ}
    (hs : s ∉ ordinaryCriticalValues (laurentOnAffineTorus f) (laurentDifferentialNorm f)) :
    RegularLaurentValue f s

theorem GoodBase.segment {d : ℕ} {f : MultiLaurent d} {D : Set ℂ}
    (hD : GoodBase f D) (hc : Convex ℝ D) {s t : ℂ} (hs : s ∈ D) (ht : t ∈ D) :
    GoodSegment f s (t - s)

theorem finite_convexHull_inter_zero {d : ℕ} {S : Set (Fin d → ℝ)} (hS : S.Finite)
    (L : (Fin d → ℝ) →L[ℝ] ℝ) (hL : ∀ x ∈ S, 0 ≤ L x) :
    convexHull ℝ (S ∩ {x | L x = 0}) = convexHull ℝ S ∩ {x | L x = 0}

theorem exists_finite_relation_chain {ι : Type*} {R : ι → ι → Prop} {i j : ι}
    (h : Relation.ReflTransGen R i j) :
    ∃ n : ℕ, ∃ u : ℕ → ι, u 0 = i ∧ u n = j ∧ ∀ k < n, R (u k) (u (k + 1))
